  1→"use client";
  2→
  3→import { useState } from "react";
  4→import { Play, Trash2, ExternalLink, Check, ChevronRight, Pencil } from "lucide-react";
  5→import { Button } from "@/components/ui/button";
  6→import { cn } from "@/lib/utils";
  7→import type { Task, TaskStatus, TaskPriority } from "@/lib/types";
  8→
  9→const PRIORITY_COLORS: Record<TaskPriority, string> = {
 10→  urgent: "bg-red-500/20 text-red-400 border-red-500/30",
 11→  high: "bg-orange-500/20 text-orange-400 border-orange-500/30",
 12→  medium: "bg-yellow-500/20 text-yellow-400 border-yellow-500/30",
 13→  low: "bg-muted text-muted-foreground border-border",
 14→};
 15→
 16→const STATUS_COLORS: Record<TaskStatus, string> = {
 17→  todo: "border-border text-muted-foreground",
 18→  "in-progress": "bg-blue-500/20 text-blue-400 border-blue-500/30",
 19→  done: "bg-green-500/20 text-green-400 border-green-500/30",
 20→};
 21→
 22→const STATUS_LABELS: Record<TaskStatus, string> = {
 23→  todo: "todo",
 24→  "in-progress": "in progress",
 25→  done: "done",
 26→};
 27→
 28→const NEXT_STATUS: Record<TaskStatus, TaskStatus> = {
 29→  todo: "in-progress",
 30→  "in-progress": "done",
 31→  done: "todo",
 32→};
 33→
 34→const PRIORITIES: TaskPriority[] = ["urgent", "high", "medium", "low"];
 35→
 36→function timeAgo(ts: number): string {
 37→  const seconds = Math.floor((Date.now() - ts) / 1000);
 38→  if (seconds < 60) return "just now";
 39→  const minutes = Math.floor(seconds / 60);
 40→  if (minutes < 60) return `${minutes}m ago`;
 41→  const hours = Math.floor(minutes / 60);
 42→  if (hours < 24) return `${hours}h ago`;
 43→  const days = Math.floor(hours / 24);
 44→  if (days < 30) return `${days}d ago`;
 45→  const months = Math.floor(days / 30);
 46→  return `${months}mo ago`;
 47→}
 48→
 49→interface TaskCardProps {
 50→  task: Task;
 51→  onUpdate: (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => void;
 52→  onDelete: (taskId: string) => void;
 53→  onDelegate: (taskId: string) => void;
 54→  onSelectAgent: (agentId: string) => void;
 55→}
 56→
 57→export function TaskCard({ task, onUpdate, onDelete, onDelegate, onSelectAgent }: TaskCardProps) {
 58→  const [expanded, setExpanded] = useState(false);
 59→  const [editing, setEditing] = useState(false);
 60→  const [editTitle, setEditTitle] = useState(task.title);
 61→  const [editDesc, setEditDesc] = useState(task.description);
 62→  const [editPriority, setEditPriority] = useState(task.priority);
 63→
 64→  const handleSaveEdit = () => {
 65→    if (!editTitle.trim()) return;
 66→    onUpdate(task.id, {
 67→      title: editTitle.trim(),
 68→      description: editDesc.trim(),
 69→      priority: editPriority,
 70→    });
 71→    setEditing(false);
 72→  };
 73→
 74→  const handleCancelEdit = () => {
 75→    setEditTitle(task.title);
 76→    setEditDesc(task.description);
 77→    setEditPriority(task.priority);
 78→    setEditing(false);
 79→  };
 80→
 81→  const handleCardClick = (e: React.MouseEvent) => {
 82→    if (editing) return;
 83→    const target = e.target as HTMLElement;
 84→    if (target.closest("button") || target.closest("input") || target.closest("textarea")) return;
 85→    setExpanded((v) => !v);
 86→  };
 87→
 88→  return (
 89→    <div
 90→      className={cn("group rounded-md border bg-card p-3 text-xs cursor-pointer transition-colors", expanded && "border-primary/30")}
 91→      onClick={handleCardClick}
 92→    >
 93→      <div className="flex items-start justify-between gap-2">
 94→        <div className="flex items-center gap-1.5 min-w-0">
 95→          <ChevronRight
 96→            className={cn("size-3 shrink-0 text-muted-foreground transition-transform", expanded && "rotate-90")}
 97→          />
 98→          <span
 99→            className={cn("shrink-0 rounded px-1.5 py-0.5 text-[10px] font-medium border", PRIORITY_COLORS[task.priority])}
100→          >
101→            {task.priority}
102→          </span>
103→          {editing ? (
104→            <input
105→              className="min-w-0 flex-1 bg-transparent font-medium outline-none border-b border-primary"
106→              value={editTitle}
107→              onChange={(e) => setEditTitle(e.target.value)}
108→              onKeyDown={(e) => {
109→                if (e.key === "Enter") handleSaveEdit();
110→                if (e.key === "Escape") handleCancelEdit();
111→              }}
112→              autoFocus
113→            />
114→          ) : (
115→            <span
116→              className={cn(
117→                "truncate font-medium",
118→                task.status === "done" && "line-through text-muted-foreground"
119→              )}
120→              onDoubleClick={() => {
121→                setEditTitle(task.title);
122→                setEditDesc(task.description);
123→                setEditPriority(task.priority);
124→                setEditing(true);
125→              }}
126→            >
127→              {task.title}
128→            </span>
129→          )}
130→        </div>
131→        <div className="flex shrink-0 items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
132→          {!editing && (
133→            <Button
134→              variant="ghost"
135→              size="icon-xs"
136→              onClick={() => {
137→                setEditTitle(task.title);
138→                setEditDesc(task.description);
139→                setEditPriority(task.priority);
140→                setEditing(true);
141→                setExpanded(true);
142→              }}
143→              title="Edit task"
144→            >
145→              <Pencil className="size-3" />
146→            </Button>
147→          )}
148→          {!task.agentId && task.status !== "done" && (
149→            <Button
150→              variant="ghost"
151→              size="icon-xs"
152→              onClick={() => onDelegate(task.id)}
153→              title="Delegate to agent"
154→            >
155→              <Play className="size-3" />
156→            </Button>
157→          )}
158→          <Button
159→            variant="ghost"
160→            size="icon-xs"
161→            onClick={() => onDelete(task.id)}
162→            title="Delete task"
163→          >
164→            <Trash2 className="size-3" />
165→          </Button>
166→        </div>
167→      </div>
168→
169→      {editing ? (
170→        <div className="mt-2 space-y-2">
171→          <textarea
172→            className="w-full rounded border bg-transparent p-1.5 text-xs outline-none resize-none focus:border-primary"
173→            value={editDesc}
174→            onChange={(e) => setEditDesc(e.target.value)}
175→            rows={2}
176→            placeholder="Description..."
177→          />
178→          <div className="flex items-center gap-1">
179→            <span className="text-[10px] text-muted-foreground mr-1">priority</span>
180→            {PRIORITIES.map((p) => (
181→              <button
182→                key={p}
183→                className={cn(
184→                  "rounded px-1.5 py-0.5 text-[10px] font-medium border transition-colors",
185→                  editPriority === p ? PRIORITY_COLORS[p] : "border-transparent text-muted-foreground/50 hover:text-muted-foreground"
186→                )}
187→                onClick={() => setEditPriority(p)}
188→              >
189→                {p}
190→              </button>
191→            ))}
192→          </div>
193→          <div className="flex gap-1">
194→            <Button size="xs" onClick={handleSaveEdit}>
195→              <Check className="size-3 mr-1" />
196→              Save
197→            </Button>
198→            <Button size="xs" variant="ghost" onClick={handleCancelEdit}>
199→              Cancel
200→            </Button>
201→          </div>
202→        </div>
203→      ) : expanded ? (
204→        <div className="mt-2 space-y-2">
205→          {task.description && (
206→            <p className="text-muted-foreground whitespace-pre-wrap">{task.description}</p>
207→          )}
208→
209→          {/* Priority selector */}
210→          <div className="flex items-center gap-1">
211→            <span className="text-muted-foreground mr-1">priority</span>
212→            {PRIORITIES.map((p) => (
213→              <button
214→                key={p}
215→                className={cn(
216→                  "rounded px-1.5 py-0.5 text-[10px] font-medium border transition-colors",
217→                  task.priority === p ? PRIORITY_COLORS[p] : "border-transparent text-muted-foreground/50 hover:text-muted-foreground"
218→                )}
219→                onClick={() => onUpdate(task.id, { priority: p })}
220→              >
221→                {p}
222→              </button>
223→            ))}
224→          </div>
225→
226→          {/* Metadata */}
227→          <div className="flex flex-col gap-0.5 text-[10px] text-muted-foreground/70">
228→            <span>created {timeAgo(task.createdAt)}</span>
229→            {task.updatedAt !== task.createdAt && (
230→              <span>updated {timeAgo(task.updatedAt)}</span>
231→            )}
232→            <span className="font-mono">id: {task.id}</span>
233→          </div>
234→        </div>
235→      ) : (
236→        task.description && (
237→          <p className="mt-1 text-muted-foreground line-clamp-2">{task.description}</p>
238→        )
239→      )}
240→
241→      <div className="mt-2 flex items-center justify-between">
242→        <button
243→          className={cn(
244→            "rounded-full border px-2 py-0.5 text-[10px] font-medium transition-colors hover:brightness-125",
245→            STATUS_COLORS[task.status]
246→          )}
247→          onClick={() => onUpdate(task.id, { status: NEXT_STATUS[task.status] })}
248→          title={`Click to change to "${STATUS_LABELS[NEXT_STATUS[task.status]]}"`}
249→        >
250→          {STATUS_LABELS[task.status]}
251→        </button>
252→
253→        {task.agentId && (
254→          <button
255→            className="flex items-center gap-1 text-[10px] text-primary hover:underline"
256→            onClick={() => onSelectAgent(task.agentId!)}
257→          >
258→            <ExternalLink className="size-2.5" />
259→            view agent
260→          </button>
261→        )}
262→      </div>
263→    </div>
264→  );
265→}
