```typescript
const COLUMNS: { status: TaskStatus; label: string; color: string }[] = [
  { status: "todo", label: "Todo", color: "text-muted-foreground" },
  { status: "in-progress", label: "In Progress", color: "text-blue-400" },
  { status: "done", label: "Done", color: "text-green-400" },
];

function KanbanColumn({
  status,
  label,
  color,
  tasks,
  onDrop,
  // ... card action props passed through
}: { ... }) {
  const [dragOver, setDragOver] = useState(false);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();          // Required to allow drop
    e.dataTransfer.dropEffect = "move";
  };

  const handleDragEnter = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    // Only clear if leaving the column itself, not entering a child
    if (e.currentTarget.contains(e.relatedTarget as Node)) return;
    setDragOver(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    const taskId = e.dataTransfer.getData("text/plain");
    if (taskId) onDrop(taskId, status);
  };

  return (
    <div
      className={cn(
        "flex flex-col rounded-lg border bg-muted/20 transition-colors",
        dragOver && "border-primary/50 bg-primary/5"
      )}
      onDragOver={handleDragOver}
      onDragEnter={handleDragEnter}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      <div className="flex items-center justify-between px-3 py-2 border-b">
        <span className={cn("text-xs font-semibold", color)}>
          {label} ({tasks.length})
        </span>
      </div>
      <div className="flex-1 overflow-y-auto p-2 space-y-2">
        {tasks.map((task) => (
          <DraggableTaskCard key={task.id} task={task} ... />
        ))}
        {tasks.length === 0 && (
          <div className="text-center text-xs text-muted-foreground/50 py-8">
            No tasks
          </div>
        )}
      </div>
    </div>
  );
}
```

#### Step 3: Create `DraggableTaskCard` wrapper

A thin wrapper around the existing `TaskCard` that adds `draggable` and drag event handlers. This avoids modifying `TaskCard` itself.

```typescript
function DraggableTaskCard({
  task,
  ...cardProps
}: TaskCardProps) {
  const [dragging, setDragging] = useState(false);

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData("text/plain", task.id);
    e.dataTransfer.effectAllowed = "move";
    setDragging(true);
  };

  const handleDragEnd = () => {
    setDragging(false);
  };

  return (
    <div
      draggable
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
      className={cn("transition-opacity", dragging && "opacity-40")}
    >
      <TaskCard task={task} {...cardProps} />
    </div>
  );
}
```

The drag wrapper uses a `<div>` around `TaskCard`. The existing `TaskCard` component already renders as a `<div>` with `cursor-pointer`, so the draggable wrapper works naturally. The opacity reduction during drag provides visual feedback that the card is being moved.

#### Step 4: Modify `app/dashboard/page.tsx` layout

The key layout change: when `showTasks` is true, replace the chat area with the kanban board instead of showing a narrow side panel.

