"use client";

import { useMemo, useState, useCallback } from "react";
import { Menu, Plus, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { TaskCard } from "./task-card";
import { TaskCreateForm } from "./task-create-form";
import type { Task, TaskPriority, TaskStatus } from "@/lib/types";

interface KanbanBoardProps {
  tasks: Task[];
  onCreateTask: (title: string, description: string, priority: TaskPriority) => void;
  onUpdateTask: (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => void;
  onDeleteTask: (taskId: string) => void;
  onDelegateTask: (taskId: string) => void;
  onSelectAgent: (agentId: string) => void;
  onClose: () => void;
  onToggleSidebar?: () => void;
}

const COLUMNS: { status: TaskStatus; label: string; color: string }[] = [
  { status: "icebox", label: "Icebox", color: "text-purple-400" },
  { status: "todo", label: "Todo", color: "text-muted-foreground" },
  { status: "in-progress", label: "In Progress", color: "text-blue-400" },
  { status: "done", label: "Done", color: "text-green-400" },
];

export function KanbanBoard({
  tasks,
  onCreateTask,
  onUpdateTask,
  onDeleteTask,
  onDelegateTask,
  onSelectAgent,
  onClose,
  onToggleSidebar,
}: KanbanBoardProps) {
  const [showCreate, setShowCreate] = useState(false);

  const grouped = useMemo(() => {
    const icebox = tasks.filter((t) => t.status === "icebox");
    const todo = tasks.filter((t) => t.status === "todo");
    const inProgress = tasks.filter((t) => t.status === "in-progress");
    const done = tasks.filter((t) => t.status === "done");
    return { icebox, todo, "in-progress": inProgress, done };
  }, [tasks]);

  const handleDrop = useCallback(
    (taskId: string, newStatus: TaskStatus) => {
      const task = tasks.find((t) => t.id === taskId);
      if (!task || task.status === newStatus) return;
      onUpdateTask(taskId, { status: newStatus });
    },
    [tasks, onUpdateTask]
  );

  return (
    <div className="flex h-full flex-col">
      {/* Header */}
      <div className="flex items-center justify-between border-b px-4 py-2">
        <div className="flex items-center gap-2">
          {onToggleSidebar && (
            <Button
              variant="ghost"
              size="icon-xs"
              onClick={onToggleSidebar}
              title="Toggle sidebar"
              className="md:hidden"
            >
              <Menu className="size-3.5" />
            </Button>
          )}
          <span className="text-xs font-semibold">Tasks</span>
        </div>
        <div className="flex items-center gap-1">
          <Button
            variant="ghost"
            size="icon-xs"
            onClick={() => setShowCreate((v) => !v)}
            title="New task"
          >
            <Plus className="size-3.5" />
          </Button>
          <Button variant="ghost" size="icon-xs" onClick={onClose} title="Close board">
            <X className="size-3.5" />
          </Button>
        </div>
      </div>

      {/* Create form */}
      {showCreate && (
        <div className="border-b">
          <TaskCreateForm
            onCreate={(title, description, priority) => {
              onCreateTask(title, description, priority);
              setShowCreate(false);
            }}
          />
        </div>
      )}

      {/* Kanban columns */}
      <div className="flex flex-1 gap-3 overflow-x-auto p-3">
        {COLUMNS.map((col) => (
          <KanbanColumn
            key={col.status}
            status={col.status}
            label={col.label}
            color={col.color}
            tasks={grouped[col.status]}
            onDrop={handleDrop}
            onUpdateTask={onUpdateTask}
            onDeleteTask={onDeleteTask}
            onDelegateTask={onDelegateTask}
            onSelectAgent={onSelectAgent}
          />
        ))}
      </div>
    </div>
  );
}

function KanbanColumn({
  status,
  label,
  color,
  tasks,
  onDrop,
  onUpdateTask,
  onDeleteTask,
  onDelegateTask,
  onSelectAgent,
}: {
  status: TaskStatus;
  label: string;
  color: string;
  tasks: Task[];
  onDrop: (taskId: string, newStatus: TaskStatus) => void;
  onUpdateTask: (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => void;
