  const handleDragEnd = () => {
    setDragging(false);
  };

  return (
    <div
      draggable
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
      className={cn("transition-opacity", dragging && "opacity-40")}
    >
      <TaskCard
        task={task}
        onUpdate={onUpdate}
        onDelete={onDelete}
        onDelegate={onDelegate}
        onSelectAgent={onSelectAgent}
      />
    </div>
  );
}

