"use client";

import { useMemo, useState, useCallback } from "react";
import { Plus, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { TaskCard } from "./task-card";
import { TaskCreateForm } from "./task-create-form";
import type { Task, TaskPriority, TaskStatus } from "@/lib/types";

interface KanbanBoardProps {
  tasks: Task[];
  onCreateTask: (title: string, description: string, priority: TaskPriority) => void;
  onUpdateTask: (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => void;
  onDeleteTask: (taskId: string) => void;
  onDelegateTask: (taskId: string) => void;
  onSelectAgent: (agentId: string) => void;
  onClose: () => void;
}

const COLUMNS: { status: TaskStatus; label: string; color: string }[] = [
  { status: "icebox", label: "Icebox", color: "text-purple-400" },
  { status: "todo", label: "Todo", color: "text-muted-foreground" },
  { status: "in-progress", label: "In Progress", color: "text-blue-400" },
  { status: "done", label: "Done", color: "text-green-400" },
];

export function KanbanBoard({
  tasks,
  onCreateTask,
  onUpdateTask,
  onDeleteTask,
  onDelegateTask,
  onSelectAgent,
  onClose,
}: KanbanBoardProps) {
  const [showCreate, setShowCreate] = useState(false);

  const grouped = useMemo(() => {
    const icebox = tasks.filter((t) => t.status === "icebox");
    const todo = tasks.filter((t) => t.status === "todo");
    const inProgress = tasks.filter((t) => t.status === "in-progress");
    const done = tasks.filter((t) => t.status === "done");
    return { icebox, todo, "in-progress": inProgress, done };
  }, [tasks]);

  const handleDrop = useCallback(
    (taskId: string, newStatus: TaskStatus) => {
      const task = tasks.find((t) => t.id === taskId);
      if (!task || task.status === newStatus) return;
      onUpdateTask(taskId, { status: newStatus });
    },
    [tasks, onUpdateTask]
  );

  return (
    <div className="flex h-full flex-col">
      {/* Header */}
      <div className="flex items-center justify-between border-b px-4 py-2">
        <span className="text-xs font-semibold">Tasks</span>
        <div className="flex items-center gap-1">
          <Button
            variant="ghost"
            size="icon-xs"
            onClick={() => setShowCreate((v) => !v)}
            title="New task"
          >
            <Plus className="size-3.5" />
          </Button>
          <Button variant="ghost" size="icon-xs" onClick={onClose} title="Close board">
            <X className="size-3.5" />
          </Button>
        </div>
      </div>

      {/* Create form */}
      {showCreate && (
        <div className="border-b">
          <TaskCreateForm
            onCreate={(title, description, priority) => {
              onCreateTask(title, description, priority);
              setShowCreate(false);
            }}
          />
        </div>
      )}

      {/* Kanban columns */}
      <div className="flex flex-1 gap-3 overflow-x-auto p-3">
        {COLUMNS.map((col) => (
          <KanbanColumn
            key={col.status}
            status={col.status}
            label={col.label}
            color={col.color}
            tasks={grouped[col.status]}
            onDrop={handleDrop}
            onUpdateTask={onUpdateTask}
            onDeleteTask={onDeleteTask}
            onDelegateTask={onDelegateTask}
            onSelectAgent={onSelectAgent}
          />
        ))}
      </div>
    </div>
  );
}

function KanbanColumn({
  status,
  label,
  color,
  tasks,
  onDrop,
  onUpdateTask,
  onDeleteTask,
  onDelegateTask,
  onSelectAgent,
}: {
  status: TaskStatus;
  label: string;
  color: string;
  tasks: Task[];
  onDrop: (taskId: string, newStatus: TaskStatus) => void;
  onUpdateTask: (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => void;
  onDeleteTask: (taskId: string) => void;
  onDelegateTask: (taskId: string) => void;
  onSelectAgent: (agentId: string) => void;
}) {
  const [dragOver, setDragOver] = useState(false);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = "move";
  };

  const handleDragEnter = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    if (e.currentTarget.contains(e.relatedTarget as Node)) return;
    setDragOver(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    const taskId = e.dataTransfer.getData("text/plain");
    if (taskId) onDrop(taskId, status);
  };

  return (
    <div
      className={cn(
        "flex min-w-[240px] flex-1 flex-col rounded-lg border bg-muted/20 transition-colors",
        dragOver && "border-primary/50 bg-primary/5"
      )}
      onDragOver={handleDragOver}
      onDragEnter={handleDragEnter}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      <div className="flex items-center justify-between px-3 py-2 border-b">
        <span className={cn("text-xs font-semibold", color)}>
          {label} ({tasks.length})
        </span>
      </div>
      <div className="flex-1 overflow-y-auto p-2 space-y-2">
        {tasks.map((task) => (
          <DraggableTaskCard
            key={task.id}
            task={task}
            onUpdate={onUpdateTask}
            onDelete={onDeleteTask}
            onDelegate={onDelegateTask}
            onSelectAgent={onSelectAgent}
          />
        ))}
        {tasks.length === 0 && (
          <div className="text-center text-xs text-muted-foreground/50 py-8">
            No tasks
          </div>
        )}
      </div>
    </div>
  );
}

function DraggableTaskCard({
  task,
  onUpdate,
  onDelete,
  onDelegate,
  onSelectAgent,
}: {
  task: Task;
  onUpdate: (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => void;
  onDelete: (taskId: string) => void;
  onDelegate: (taskId: string) => void;
  onSelectAgent: (agentId: string) => void;
}) {
  const [dragging, setDragging] = useState(false);

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData("text/plain", task.id);
    e.dataTransfer.effectAllowed = "move";
    setDragging(true);
  };

  const handleDragEnd = () => {
    setDragging(false);
  };

  return (
    <div
      draggable
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
      className={cn("transition-opacity", dragging && "opacity-40")}
    >
      <TaskCard
        task={task}
        onUpdate={onUpdate}
        onDelete={onDelete}
        onDelegate={onDelegate}
        onSelectAgent={onSelectAgent}
      />
    </div>
  );
}

